-- NOAMIS 360° — initialisation (à exécuter APRÈS 01_schema_complet.sql)
-- Prérequis : créer d'abord votre compte dans Supabase → Authentication → Users → « Add user »
-- (Create new user, cocher « Auto Confirm User »), puis remplacer l'adresse ci-dessous.
-- Aucune donnée fictive n'est créée.
do $$
declare
  v_email text := 'contact@noamis.fr';   -- ← votre adresse de connexion
  v_user uuid;
  v_org uuid;
begin
  select id into v_user from auth.users where email = lower(v_email);
  if v_user is null then
    raise exception 'Créez d''abord l''utilisateur % dans Authentication → Users', v_email;
  end if;
  insert into public.profiles (id, email, full_name) values (v_user, lower(v_email), 'Direction NOAMIS') on conflict (id) do nothing;
  select id into v_org from public.organizations where is_default;
  if v_org is null then
    insert into public.organizations (name, legal_form, siren, postal_code, city, email, website, vat_regime, is_default)
    values ('NOAMIS Sûreté Conseil', 'Entrepreneur individuel', '907525158', '78100', 'Saint-Germain-en-Laye', 'contact@noamis.fr', 'https://www.noamis.fr/', 'franchise', true)
    returning id into v_org;
  end if;
  insert into public.memberships (organization_id, user_id, role) values (v_org, v_user, 'super_admin')
  on conflict (organization_id, user_id) do update set role = 'super_admin', active = true;
  raise notice 'Initialisation terminée : super-administrateur %', v_email;
end $$;

-- Modèle d'audit par défaut
insert into public.audit_templates (organization_id, name, description, categories, questions, scoring)
select id, $t$Audit de sûreté — modèle général NOAMIS$t$, $t$Grille d'observation couvrant les 8 domaines de la sûreté d'un site. À adapter selon le contexte.$t$, $tpl$[{"key":"controle_acces","label":"Contrôle d'accès"},{"key":"protection_perimetrique","label":"Protection périmétrique"},{"key":"videoprotection","label":"Vidéoprotection"},{"key":"detection_intrusion","label":"Détection intrusion"},{"key":"organisation_procedures","label":"Organisation et procédures"},{"key":"gestion_visiteurs","label":"Gestion des visiteurs"},{"key":"protection_actifs","label":"Protection des actifs"},{"key":"continuite_activite","label":"Continuité d'activité"}]$tpl$::jsonb, $tpl$[{"id":"controle_acces-1","category":"controle_acces","label":"Les accès au site sont-ils identifiés, limités en nombre et maîtrisés ?","weight":1},{"id":"controle_acces-2","category":"controle_acces","label":"Les droits d'accès sont-ils attribués nominativement et revus périodiquement ?","weight":1},{"id":"controle_acces-3","category":"controle_acces","label":"Les badges, clés et codes perdus ou restitués sont-ils désactivés sans délai ?","weight":1},{"id":"controle_acces-4","category":"controle_acces","label":"Les zones sensibles disposent-elles d'un contrôle d'accès renforcé ?","weight":1},{"id":"protection_perimetrique-1","category":"protection_perimetrique","label":"La limite de propriété est-elle matérialisée et en bon état ?","weight":1},{"id":"protection_perimetrique-2","category":"protection_perimetrique","label":"Les portails et accès véhicules sont-ils fermés hors des heures d'activité ?","weight":1},{"id":"protection_perimetrique-3","category":"protection_perimetrique","label":"L'éclairage extérieur couvre-t-il les points d'accès et zones sensibles ?","weight":1},{"id":"protection_perimetrique-4","category":"protection_perimetrique","label":"La végétation ou le mobilier extérieur ne facilitent-ils pas une intrusion ?","weight":1},{"id":"videoprotection-1","category":"videoprotection","label":"Les caméras couvrent-elles les accès et zones à enjeux définis ?","weight":1},{"id":"videoprotection-2","category":"videoprotection","label":"La qualité d'image permet-elle l'exploitation (identification, levée de doute) ?","weight":1},{"id":"videoprotection-3","category":"videoprotection","label":"La durée de conservation et l'information du public sont-elles conformes ?","guidance":"Durée proportionnée, affichage, registre de traitement.","weight":1},{"id":"videoprotection-4","category":"videoprotection","label":"L'enregistreur et les accès aux images sont-ils protégés ?","weight":1},{"id":"detection_intrusion-1","category":"detection_intrusion","label":"Un système de détection intrusion couvre-t-il les accès et volumes sensibles ?","weight":1},{"id":"detection_intrusion-2","category":"detection_intrusion","label":"Les alarmes sont-elles transmises et traitées (télésurveillance, astreinte) ?","weight":1},{"id":"detection_intrusion-3","category":"detection_intrusion","label":"Le système est-il maintenu et testé régulièrement ?","weight":1},{"id":"organisation_procedures-1","category":"organisation_procedures","label":"Un référent sûreté est-il désigné et connu du personnel ?","weight":1},{"id":"organisation_procedures-2","category":"organisation_procedures","label":"Des consignes écrites existent-elles (ouverture, fermeture, incident) ?","weight":1},{"id":"organisation_procedures-3","category":"organisation_procedures","label":"Le personnel est-il sensibilisé aux risques et aux réflexes attendus ?","weight":1},{"id":"organisation_procedures-4","category":"organisation_procedures","label":"Les incidents sont-ils consignés et analysés ?","weight":1},{"id":"gestion_visiteurs-1","category":"gestion_visiteurs","label":"Les visiteurs sont-ils enregistrés et identifiés à leur arrivée ?","weight":1},{"id":"gestion_visiteurs-2","category":"gestion_visiteurs","label":"Les visiteurs sont-ils accompagnés dans les zones non publiques ?","weight":1},{"id":"gestion_visiteurs-3","category":"gestion_visiteurs","label":"Les prestataires et livraisons font-ils l'objet d'une procédure ?","weight":1},{"id":"protection_actifs-1","category":"protection_actifs","label":"Les biens de valeur et fonds sont-ils protégés (coffre, local fermé) ?","weight":1},{"id":"protection_actifs-2","category":"protection_actifs","label":"Les informations et équipements informatiques sensibles sont-ils protégés ?","weight":1},{"id":"protection_actifs-3","category":"protection_actifs","label":"Un inventaire des actifs sensibles est-il tenu à jour ?","weight":1},{"id":"continuite_activite-1","category":"continuite_activite","label":"Les scénarios de crise majeurs ont-ils été identifiés ?","weight":1},{"id":"continuite_activite-2","category":"continuite_activite","label":"Un plan de continuité ou de reprise existe-t-il et est-il connu ?","weight":1},{"id":"continuite_activite-3","category":"continuite_activite","label":"Les contacts d'urgence et la chaîne d'alerte sont-ils à jour ?","weight":1},{"id":"continuite_activite-4","category":"continuite_activite","label":"Des exercices sont-ils organisés et suivis d'un retour d'expérience ?","weight":1}]$tpl$::jsonb, $tpl${"name":"Matrice NOAMIS 4×4 (vraisemblance × gravité)","likelihood":{"min":1,"max":4,"labels":["Rare","Possible","Probable","Quasi certain"]},"impact":{"min":1,"max":4,"labels":["Mineur","Significatif","Grave","Critique"]},"levels":[{"min":1,"max":3,"label":"Faible","tone":"success"},{"min":4,"max":6,"label":"Modéré","tone":"gold"},{"min":7,"max":9,"label":"Élevé","tone":"warning"},{"min":10,"max":16,"label":"Critique","tone":"danger"}],"criteria":[{"key":"exposition","label":"Exposition du site (environnement, historique d'incidents)"},{"key":"attractivite","label":"Attractivité des actifs pour un acteur malveillant"},{"key":"mesures","label":"Efficacité des mesures existantes"},{"key":"consequences","label":"Conséquences humaines, matérielles, d'image ou d'activité"}]}$tpl$::jsonb
from public.organizations where is_default and not exists (select 1 from public.audit_templates);
